fn reverse(a: &Vec<i32>) -> Vec<i32> {
    // Preallocate a vector with the same length as the input
    let mut a_rev = Vec::with_capacity(a.len());
    // Iterate over the input in reverse order and push each element
    for &elem in a.iter().rev() {
        a_rev.push(elem);
    }
    a_rev
}

